    disclaimerTitle: "আইনি দাবিত্যাগ ও সতর্কতা",
    disclaimerBody:
      "এই পাতায় প্রক্রিয়াটি সাধারণভাবে ব্যাখ্যা করা হয়েছে, শুধু তথ্যের জন্য। এটি আইনি বা কর-সংক্রান্ত পরামর্শ নয়। হার, মৌজা মূল্য ও পদ্ধতি বদলায় এবং এলাকাভেদে আলাদা হতে পারে। কিছু পরিশোধ বা সই করার আগে সাব-রেজিস্ট্রি অফিস, জাতীয় রাজস্ব বোর্ড (এনবিআর) বা যোগ্য আইনজীবীর কাছে বর্তমান অবস্থা যাচাই করুন।",
