    faq4Q:
      "উত্তরাধিকার সূত্রে পাওয়া পৈতৃক সম্পত্তি বিক্রিতে কী কী কাগজপত্র বাধ্যতামূলক?",
    faq4A:
      "স্থানীয় সিটি কর্পোরেশন বা ইউনিয়ন পরিষদ থেকে গৃহীত মূল ওয়ারিশান সনদ, সকল বৈধ ওয়ারিশের স্বাক্ষরে সাব-রেজিস্ট্রি অফিসে নিবন্ধিত আপস বণ্টননামা দলিল, এবং বিক্রেতার একক নামে খারিজকৃত ই-নামজারি খতিয়ান ও হালনাগাদ খাজনা দাখিলা অবশ্যই থাকতে হবে।",
    disclaimerTitle: "আইনি পরামর্শ ও সতর্কবার্তা",
    disclaimerDesc:
      "এই গাইডের তথ্যসমূহ বাংলাদেশে রিয়েল এস্টেট বিক্রয়ের সাধারণ নিয়মাবলি সম্পর্কে সচেতনতা সৃষ্টির উদ্দেশ্যে সংকলিত। জমি ও ফ্ল্যাট বিক্রয়ে জটিল আর্থিক ও উত্তরাধিকার সংক্রান্ত বিধিবিধান কার্যকর থাকে। যেকোনো চূড়ান্ত চুক্তি বা দলিল সম্পাদনের পূর্বে রেজিস্টার্ড দলিল লেখক বা অভিজ্ঞ দেওয়ানি আইনজীবীর পরামর্শ নেওয়ার জন্য বিশেষভাবে অনুরোধ করা হচ্ছে।",
