    guide2Desc:
      "বাড়ি ভাড়া চুক্তিপত্রের সংবিধিবদ্ধ স্ট্যাম্প মূল্য এবং নোটারি খরচের সঠিক হিসাব জানুন।",
    guide3Category: "শিক্ষার্থী আবাসন",
    guide3Title: "যাচাইকৃত ব্যাচেলর ও স্টুডেন্ট মেস আবাসন",
    guide3Desc:
      "ঢাকার প্রধান বিশ্ববিদ্যালয়গুলোর কাছে নির্ভরযোগ্য ব্যাচেলর মেস, হোস্টেল ও সাবলেট তালিকা দেখুন।",
    guide4Category: "প্রপার্টি সার্চ",
    guide4Title: "ঢাকায় ভাড়ার জন্য অ্যাপার্টমেন্ট ও বাসা খুঁজুন",
    guide4Desc:
      "ঢাকার বিভিন্ন এলাকায় যাচাইকৃত হাজারো আবাসিক ফ্ল্যাট ও ফ্যামিলি অ্যাপার্টমেন্টের তালিকা এক্সপ্লোর করুন।",
    guide5Category: "মূল্যায়ন",
    guide5Title: "প্রপার্টি ভ্যালুয়েশন ও রেন্টাল ইল্ড ক্যালকুলেটর",
    guide5Desc:
      "সম্পত্তির বাজারমূল্য ও মাসিক ভাড়ার অনুপাত বিশ্লেষণ করে আপনার প্রস্তাবিত ভাড়া যৌক্তিক কিনা যাচাই করুন।",
    faqTitle: "ভাড়াটিয়াদের সাধারণ আইনি প্রশ্নোত্তর",
    faqSubtitle:
      "ইউটিলিটি বিচ্ছিন্নকরণ, জামানত ফেরত এবং রেন্ট কন্ট্রোলার আদালত সংক্রান্ত সমাধান।",
    faq1Q:
      "ভাড়ার বিরোধ হলে বাড়িওয়ালা কি গ্যাস, পানি বা বিদ্যুৎ সংযোগ বিচ্ছিন্ন করতে পারেন?",
    faq1A:
      "না, কোনোভাবেই পারেন না। বাড়ি ভাড়া নিয়ন্ত্রণ আইন ১৯৯১-এর ধারা ১৮ অনুযায়ী রেন্ট কন্ট্রোলারের আদালতের আদেশ ব্যতীত গ্যাস, বিদ্যুৎ, পানি বা লিফটের সংযোগ বিচ্ছিন্ন করা একটি দণ্ডনীয় ফৌজদারি অপরাধ। এমন ঘটনা ঘটলে ভাড়াটিয়া অবিলম্বে রেন্ট কন্ট্রোলারের আদালতে জরুরি আবেদন করে সংযোগ পুনর্বহালের আদেশ নিতে পারেন।",
    faq2Q:
      "বাংলাদেশে অগ্রিম ভাড়া বা জামানত গ্রহণের সংবিধিবদ্ধ আইনি সীমা কতটুকু?",
    faq2A:
      "বাড়ি ভাড়া নিয়ন্ত্রণ আইন ১৯৯১-এর ধারা ১০ অনুযায়ী কোনো বাড়িওয়ালা আবাসিক বাড়ি ভাড়ার শর্ত হিসেবে ১ মাসের বেশি অগ্রিম ভাড়া বা কোনো ধরনের সালামি/প্রিমিয়াম দাবি করতে পারেন না। তবে বর্তমান ঢাকা শহরের বাস্তবতায় সাধারণত ১ থেকে ২ মাসের ভাড়া জামানত হিসেবে রাখা হয় যা লিখিতভাবে ফেরতযোগ্য হিসেবে উল্লেখ থাকা আবশ্যক।",
    faq3Q:
      "ডিএমপির ভাড়াটিয়া তথ্য ফরম (CIMS) কীভাবে ভাড়াটিয়াকে আইনি সুরক্ষা দেয়?",
    faq3A:
      "থানায় সিআইএমএস ফরম জমা দেওয়া থাকলে উক্ত ঠিকানায় ভাড়াটিয়ার বৈধ বসবাসের আনুষ্ঠানিক সরকারি প্রমাণ তৈরি হয়। এটি বাড়িওয়ালার অন্যায় উচ্ছেদ বা মিথ্যা অভিযোগ থেকে রক্ষা করে এবং নাগরিক অধিকার নিশ্চিত করে।",
    faq4Q:
      "বাসা ছাড়ার পর বাড়িওয়ালা জামানতের টাকা ফেরত দিতে অস্বীকৃতি জানালে কী করণীয়?",
    faq4A:
      "ইউটিলিটি বিল ক্লিয়ার করে বাসা খালি করে দেওয়ার পর বাড়িওয়ালা জামানত আটকে রাখলে প্রথমে একজন আইনজীবীর মাধ্যমে লিগ্যাল নোটিশ পাঠাতে হবে। এতে কাজ না হলে বাড়ি ভাড়া নিয়ন্ত্রণ আইন ১৯৯১ অনুযায়ী রেন্ট কন্ট্রোলারের আদালতে আবেদন অথবা দেওয়ানি আদালতে মানি স্যুট দায়ের করে আইনগতভাবে টাকা আদায় করা যায়।",
    disclaimerTitle: "আইনি ও সংবিধিবদ্ধ সতর্কবার্তা",
    disclaimerDesc:
      "এই গাইডের তথ্যাবলি বাড়ি ভাড়া নিয়ন্ত্রণ আইন ১৯৯১ ও পুলিশি নিরাপত্তা নির্দেশিকার আলোকে সচেতনতার উদ্দেশ্যে প্রস্তুত। বাড়ি ভাড়া একটি সংবিধিবদ্ধ চুক্তি। যেকোনো অনাকাঙ্ক্ষিত উচ্ছেদ বা বিরোধে আদালতের দ্বারস্থ হওয়ার পূর্বে অভিজ্ঞ দেওয়ানি আইনজীবী বা স্থানীয় সালিশের সহায়তা নেওয়ার পরামর্শ দেওয়া হচ্ছে।",
